{
  "book_code": "TADAM",
  "verses": [
    {
      "chapter": 42,
      "verse": 5,
      "text_ar": "الماء والروح القدس إلى الحياة الأبدية. ثم إن ابن الله المحبوب جداً، المسيح، نازلاً على الأرض، سيقود أباك آدم إلى الفردوس وإلى شجرة الرحمة.]"
    },
    {
      "chapter": 43,
      "verse": 1,
      "text_ar": "'وأما أنت يا شيث، فاذهب إلى أبيك آدم، إذ قد تمّ زمان حياته. فبعد ستة أيام، تخرج نفسه من جسده، وحين تخرج، ستعاين عجائب عظيمة في السماء وعلى الأرض و"
    },
    {
      "chapter": 43,
      "verse": 2,
      "text_ar": "نيرات السماء.' وبهذه الكلمات، انصرف ميخائيل للتو عن شيث."
    },
    {
      "chapter": 43,
      "verse": 3,
      "text_ar": "ورجعت حواء وشيث حاملين معهما أعشاباً ذات رائحة طيبة، أي الناردين والزعفران والقصب والقرفة."
    },
    {
      "chapter": 44,
      "verse": 1,
      "text_ar": "ولما بلغ شيث وأمه آدم، أخبراه بما فعله الوحش [الحية]."
    }
  ]
}
